"""
JavaScript engine for NCERT Class 5 Mathematics - Chapter 3: Angles as Turns
"""

js_code = '\n// State variables\nlet currentSlide = 1;\nconst totalSlides = 20;\nlet isSpeaking = false;\nlet currentUtterance = null;\nlet watchdogInterval = null;\nlet currentAudioText = "";\n\n// Voice configuration\nlet selectedVoice = null;\nlet availableVoices = [];\n\n// Sound effects using Web Audio API\nconst audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n\nfunction playSound(type) {\n    if (audioCtx.state === \'suspended\') {\n        audioCtx.resume();\n    }\n    const osc = audioCtx.createOscillator();\n    const gain = audioCtx.createGain();\n    osc.connect(gain);\n    gain.connect(audioCtx.destination);\n    const now = audioCtx.currentTime;\n\n    if (type === \'correct\') {\n        osc.type = \'triangle\';\n        osc.frequency.setValueAtTime(440, now);\n        osc.frequency.exponentialRampToValueAtTime(880, now + 0.2);\n        gain.gain.setValueAtTime(0.2, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);\n        osc.start(now);\n        osc.stop(now + 0.25);\n    } else if (type === \'incorrect\') {\n        osc.type = \'sawtooth\';\n        osc.frequency.setValueAtTime(260, now);\n        osc.frequency.exponentialRampToValueAtTime(130, now + 0.25);\n        gain.gain.setValueAtTime(0.25, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);\n        osc.start(now);\n        osc.stop(now + 0.3);\n    } else if (type === \'click\') {\n        osc.type = \'sine\';\n        osc.frequency.setValueAtTime(600, now);\n        gain.gain.setValueAtTime(0.1, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);\n        osc.start(now);\n        osc.stop(now + 0.08);\n    }\n}\n\n// Strictly pure male voices filter\nfunction isIndianMaleVoice(v) {\n    const name = v.name.toLowerCase();\n    const lang = (v.lang || \'\').toLowerCase();\n    const femaleKeywords = [\n        \'female\', \'woman\', \'girl\', \'lady\', \'zira\', \'aria\', \'jenny\', \'heera\',\n        \'neerja\', \'priya\', \'swara\', \'veena\', \'google us english\',\n        \'google indian english\', \'google uk english female\', \'google हिन्दी\'\n    ];\n    if (femaleKeywords.some(kw => name.includes(kw))) return false;\n\n    const indianMaleKeywords = [\'prabhat\', \'rishi\', \'ravi\', \'pradeep\', \'madhav\', \'karan\', \'mohan\'];\n    if (indianMaleKeywords.some(kw => name.includes(kw))) return true;\n\n    if ((lang.includes(\'en-in\') || lang.includes(\'en_in\')) && !femaleKeywords.some(kw => name.includes(kw))) {\n        if (name.includes(\'male\') || !name.includes(\'google\')) return true;\n    }\n    return false;\n}\n\nfunction isGeneralMaleVoice(v) {\n    const name = v.name.toLowerCase();\n    const lang = (v.lang || \'\').toLowerCase();\n    const femaleKeywords = [\n        \'female\', \'woman\', \'girl\', \'lady\', \'zira\', \'aria\', \'jenny\', \'heera\',\n        \'neerja\', \'priya\', \'swara\', \'veena\', \'google us english\',\n        \'google indian english\', \'google uk english female\', \'google हिन्दी\'\n    ];\n    if (femaleKeywords.some(kw => name.includes(kw))) return false;\n\n    if (name.includes(\'uk english male\') || name.includes(\'male\') || name.includes(\'david\') || name.includes(\'mark\') || name.includes(\'alex\') || name.includes(\'daniel\')) {\n        return true;\n    }\n    return false;\n}\n\nfunction initVoices() {\n    if (!(\'speechSynthesis\' in window)) return;\n    const voices = window.speechSynthesis.getVoices();\n    if (!voices || voices.length === 0) return;\n\n    availableVoices = voices;\n    const voiceSelect = document.getElementById(\'voiceSelect\');\n    if (voiceSelect) {\n        voiceSelect.innerHTML = \'\';\n    }\n\n    let indianMale = voices.find(isIndianMaleVoice);\n    let ukMale = voices.find(v => v.name.toLowerCase().includes(\'google uk english male\'));\n    let generalMale = voices.find(isGeneralMaleVoice);\n\n    if (indianMale) {\n        selectedVoice = indianMale;\n    } else if (ukMale) {\n        selectedVoice = ukMale;\n    } else if (generalMale) {\n        selectedVoice = generalMale;\n    } else {\n        selectedVoice = voices[0];\n    }\n\n    voices.forEach((v, idx) => {\n        const isInd = isIndianMaleVoice(v);\n        const isGenMale = isGeneralMaleVoice(v);\n        const option = document.createElement(\'option\');\n        option.value = idx;\n        let badge = \'\';\n        if (isInd) badge = \' 🇮🇳 [Indian Male Teacher]\';\n        else if (isGenMale) badge = \' 👨 [Male Teacher]\';\n        option.textContent = `${v.name} (${v.lang})${badge}`;\n\n        if (v === selectedVoice) {\n            option.selected = true;\n        }\n        if (voiceSelect) {\n            voiceSelect.appendChild(option);\n        }\n    });\n}\n\nfunction onVoiceChange() {\n    const voiceSelect = document.getElementById(\'voiceSelect\');\n    if (!voiceSelect || !availableVoices.length) return;\n    const idx = parseInt(voiceSelect.value, 10);\n    if (!isNaN(idx) && availableVoices[idx]) {\n        selectedVoice = availableVoices[idx];\n        if (isSpeaking) {\n            stopAudio();\n            playCurrentSlideAudio();\n        }\n    }\n}\n\n// Web Speech Watchdog Timer\nfunction startWatchdog() {\n    stopWatchdog();\n    watchdogInterval = setInterval(() => {\n        if (isSpeaking && window.speechSynthesis.speaking) {\n            window.speechSynthesis.pause();\n            window.speechSynthesis.resume();\n        }\n    }, 10000);\n}\n\nfunction stopWatchdog() {\n    if (watchdogInterval) {\n        clearInterval(watchdogInterval);\n        watchdogInterval = null;\n    }\n}\n\n// Spoken Classroom Lecture\nfunction playCurrentSlideAudio() {\n    if (!(\'speechSynthesis\' in window)) {\n        alert("Text-to-speech is not supported in this browser.");\n        return;\n    }\n    window.speechSynthesis.cancel();\n    stopWatchdog();\n\n    const slideData = slidesData.find(s => s.id === currentSlide);\n    if (!slideData || !slideData.audio_text) return;\n\n    currentAudioText = slideData.audio_text;\n    currentUtterance = new SpeechSynthesisUtterance(currentAudioText);\n\n    if (selectedVoice) {\n        currentUtterance.voice = selectedVoice;\n    }\n\n    const voiceName = (selectedVoice ? selectedVoice.name : \'\').toLowerCase();\n    const isMale = isIndianMaleVoice(selectedVoice || {}) || isGeneralMaleVoice(selectedVoice || {});\n\n    // Acoustic male calibration\n    currentUtterance.pitch = isMale ? 0.85 : 0.55;\n    currentUtterance.rate = 0.94;\n\n    currentUtterance.onstart = () => {\n        isSpeaking = true;\n        startWatchdog();\n        updateAudioButtonUI(true);\n    };\n\n    currentUtterance.onend = () => {\n        isSpeaking = false;\n        stopWatchdog();\n        updateAudioButtonUI(false);\n    };\n\n    currentUtterance.onerror = (e) => {\n        console.warn("Speech synthesis error or cancelled:", e);\n        isSpeaking = false;\n        stopWatchdog();\n        updateAudioButtonUI(false);\n    };\n\n    window.speechSynthesis.speak(currentUtterance);\n}\n\nfunction stopAudio() {\n    if (\'speechSynthesis\' in window) {\n        window.speechSynthesis.cancel();\n    }\n    isSpeaking = false;\n    stopWatchdog();\n    updateAudioButtonUI(false);\n}\n\nfunction toggleAudio() {\n    if (isSpeaking) {\n        stopAudio();\n    } else {\n        playCurrentSlideAudio();\n    }\n}\n\nfunction updateAudioButtonUI(speaking) {\n    const playIcon = document.getElementById(\'audioPlayIcon\');\n    const pauseIcon = document.getElementById(\'audioPauseIcon\');\n    const audioBtnText = document.getElementById(\'audioBtnText\');\n    const audioPulse = document.getElementById(\'audioPulse\');\n\n    if (speaking) {\n        if (playIcon) playIcon.classList.add(\'hidden\');\n        if (pauseIcon) pauseIcon.classList.remove(\'hidden\');\n        if (audioBtnText) audioBtnText.textContent = \'Pause Lecture\';\n        if (audioPulse) audioPulse.classList.remove(\'hidden\');\n    } else {\n        if (playIcon) playIcon.classList.remove(\'hidden\');\n        if (pauseIcon) pauseIcon.classList.add(\'hidden\');\n        if (audioBtnText) audioBtnText.textContent = \'Listen Lecture\';\n        if (audioPulse) audioPulse.classList.add(\'hidden\');\n    }\n}\n\n// Navigation\nfunction goToSlide(n) {\n    if (n < 1 || n > totalSlides) return;\n    stopAudio();\n    currentSlide = n;\n\n    // Show active slide\n    for (let i = 1; i <= totalSlides; i++) {\n        const el = document.getElementById(`slide-${i}`);\n        if (el) {\n            if (i === currentSlide) {\n                el.classList.remove(\'hidden\');\n            } else {\n                el.classList.add(\'hidden\');\n            }\n        }\n    }\n\n    // Update Slide Counter\n    const counter = document.getElementById(\'slideCounter\');\n    if (counter) counter.textContent = `Slide ${currentSlide} of ${totalSlides}`;\n\n    // Update Progress Bar & Dots\n    const progressFill = document.getElementById(\'progressFill\');\n    if (progressFill) {\n        const pct = ((currentSlide - 1) / (totalSlides - 1)) * 100;\n        progressFill.style.width = `${pct}%`;\n    }\n\n    for (let i = 1; i <= totalSlides; i++) {\n        const dot = document.getElementById(`dot-${i}`);\n        if (dot) {\n            if (i === currentSlide) {\n                dot.className = \'w-3 h-3 rounded-full bg-amber-400 ring-2 ring-amber-300 scale-125 transition-all\';\n            } else if (i < currentSlide) {\n                dot.className = \'w-2 h-2 rounded-full bg-emerald-400 hover:bg-emerald-300 cursor-pointer transition-all\';\n            } else {\n                dot.className = \'w-2 h-2 rounded-full bg-slate-600 hover:bg-slate-400 cursor-pointer transition-all\';\n            }\n        }\n    }\n\n    // Terminal Slide Invariant\n    const nextBtn = document.getElementById(\'nextBtn\');\n    const lastSlideNotice = document.getElementById(\'lastSlideNotice\');\n    if (currentSlide === totalSlides) {\n        if (nextBtn) nextBtn.style.display = \'none\';\n        if (lastSlideNotice) lastSlideNotice.classList.remove(\'hidden\');\n    } else {\n        if (nextBtn) nextBtn.style.display = \'inline-flex\';\n        if (lastSlideNotice) lastSlideNotice.classList.add(\'hidden\');\n    }\n\n    const prevBtn = document.getElementById(\'prevBtn\');\n    if (prevBtn) {\n        if (currentSlide === 1) {\n            prevBtn.disabled = true;\n            prevBtn.classList.add(\'opacity-40\', \'cursor-not-allowed\');\n        } else {\n            prevBtn.disabled = false;\n            prevBtn.classList.remove(\'opacity-40\', \'cursor-not-allowed\');\n        }\n    }\n\n    // Initialize Simulator on First Load\n    initSlideSimulator(currentSlide);\n    window.scrollTo({ top: 0, behavior: \'smooth\' });\n}\n\nfunction nextSlide() {\n    if (currentSlide < totalSlides) {\n        playSound(\'click\');\n        goToSlide(currentSlide + 1);\n    }\n}\n\nfunction prevSlide() {\n    if (currentSlide > 1) {\n        playSound(\'click\');\n        goToSlide(currentSlide - 1);\n    }\n}\n\n// Checkpoint Interaction\nfunction handleCheckpoint(slideId, cpIdx, optIdx, isCorrect, feedback) {\n    const optionsContainer = document.getElementById(`cp-${slideId}-${cpIdx}-options`);\n    const feedbackBox = document.getElementById(`cp-${slideId}-${cpIdx}-fb`);\n    if (!optionsContainer) return;\n\n    const buttons = optionsContainer.querySelectorAll(\'button\');\n    buttons.forEach((btn, idx) => {\n        btn.disabled = true;\n        if (idx === optIdx) {\n            if (isCorrect) {\n                btn.className = \'w-full text-left p-3 rounded-xl bg-emerald-500/20 border-2 border-emerald-400 text-emerald-200 text-xs font-semibold flex items-center justify-between shadow-lg\';\n                btn.innerHTML += \'<span class="text-emerald-400 font-bold ml-2">✓ Correct</span>\';\n                playSound(\'correct\');\n            } else {\n                btn.className = \'w-full text-left p-3 rounded-xl bg-rose-500/20 border-2 border-rose-400 text-rose-200 text-xs font-semibold flex items-center justify-between shadow-lg\';\n                btn.innerHTML += \'<span class="text-rose-400 font-bold ml-2">✗ Incorrect</span>\';\n                playSound(\'incorrect\');\n            }\n        } else {\n            btn.classList.add(\'opacity-50\');\n        }\n    });\n\n    if (feedbackBox) {\n        feedbackBox.textContent = feedback;\n        feedbackBox.className = `mt-3 p-3 rounded-xl text-xs font-medium border ${isCorrect ? \'bg-emerald-950/70 border-emerald-500/40 text-emerald-200\' : \'bg-rose-950/70 border-rose-500/40 text-rose-200\'}`;\n        feedbackBox.classList.remove(\'hidden\');\n    }\n}\n\n// Mastery Quiz Modal\nfunction handleQuizOption(slideId, qIdx, optIdx, isCorrect) {\n    const optionsContainer = document.getElementById(`quiz-${slideId}-${qIdx}-options`);\n    if (!optionsContainer) return;\n\n    const buttons = optionsContainer.querySelectorAll(\'button\');\n    buttons.forEach((btn, idx) => {\n        btn.disabled = true;\n        if (idx === optIdx) {\n            if (isCorrect) {\n                btn.className = \'w-full text-left p-2.5 rounded-lg bg-emerald-500/20 border border-emerald-400 text-emerald-200 text-xs font-semibold flex items-center justify-between\';\n                btn.innerHTML += \'<span class="text-emerald-400 font-bold">✓</span>\';\n                playSound(\'correct\');\n            } else {\n                btn.className = \'w-full text-left p-2.5 rounded-lg bg-rose-500/20 border border-rose-400 text-rose-200 text-xs font-semibold flex items-center justify-between\';\n                btn.innerHTML += \'<span class="text-rose-400 font-bold">✗</span>\';\n                playSound(\'incorrect\');\n            }\n        } else {\n            btn.classList.add(\'opacity-40\');\n        }\n    });\n\n    const solBtn = document.getElementById(`quiz-${slideId}-${qIdx}-solBtn`);\n    if (solBtn) {\n        solBtn.classList.remove(\'hidden\');\n    }\n}\n\nfunction showQuizSolution(slideId, qIdx) {\n    const slideData = slidesData.find(s => s.id === slideId);\n    if (!slideData || !slideData.quizzes || !slideData.quizzes[qIdx]) return;\n    const q = slideData.quizzes[qIdx];\n\n    const modalTitle = document.getElementById(\'solutionModalTitle\');\n    const modalBody = document.getElementById(\'solutionModalBody\');\n    const modal = document.getElementById(\'solutionModal\');\n\n    if (modalTitle) modalTitle.textContent = `Solution: Question ${qIdx + 1}`;\n    if (modalBody) {\n        modalBody.innerHTML = `\n            <div class="mb-3 font-semibold text-slate-200">${q.question}</div>\n            <div class="p-3 bg-emerald-950/50 border border-emerald-500/40 rounded-xl text-emerald-200 text-xs leading-relaxed mb-3">\n                <span class="font-bold text-emerald-300">Correct Answer:</span> ${q.options[q.correct]}\n            </div>\n            <div class="p-3 bg-slate-800/80 rounded-xl text-slate-300 text-xs leading-relaxed border border-slate-700">\n                <span class="font-bold text-amber-300">Explanation & Rule:</span><br>\n                ${q.solution_html}\n            </div>\n        `;\n    }\n    if (modal) {\n        modal.classList.remove(\'hidden\');\n        playSound(\'click\');\n    }\n}\n\nfunction closeSolutionModal() {\n    const modal = document.getElementById(\'solutionModal\');\n    if (modal) modal.classList.add(\'hidden\');\n}\n\n// ----------------------------------------------------------------------------\n// SIMULATOR LOGIC ENGINES (1 to 16)\n// ----------------------------------------------------------------------------\n\nfunction initSlideSimulator(id) {\n    switch(id) {\n        case 1: s1SetTurn(0, \'0 Turns\'); break;\n        case 2: s2SetTurn(0, \'0/4 Turn (0°)\'); break;\n        case 3: s3UpdateAngle(45); break;\n        case 4: s4SetPreset(90, \'Exact Right Angle (90°)\'); break;\n        case 5: s5Update(35); break;\n        case 6: s6Update(125); break;\n        case 7: s7Step(0); break;\n        case 8: s8SetAngle(90); break;\n        case 9: s9SelectObject(\'door\'); break;\n        case 10: s10ShowStep(0); break;\n        case 11: s11SetSector(1); break;\n        case 12: s12SetFormula(\'1/4 + 1/8\', 135); break;\n        case 13: s13InitClock(); s13SetMinutes(15); break;\n        case 14: s14Reset(); break;\n        case 15: s15Reset(); break;\n        case 16: s16Reset(); break;\n    }\n}\n\n// Sim 1: Giant Wheel\nlet s1Angle = 0;\nfunction s1SetTurn(deg, text) {\n    s1Angle = deg;\n    const g = document.getElementById(\'s1WheelGroup\');\n    const readout = document.getElementById(\'s1TurnReadout\');\n    const slider = document.getElementById(\'s1Slider\');\n    if (g) g.setAttribute(\'transform\', `rotate(${deg})`);\n    if (readout) readout.textContent = `${deg}° (${text})`;\n    if (slider) slider.value = deg;\n    playSound(\'click\');\n}\nfunction s1OnSlider(val) {\n    s1Angle = parseInt(val, 10);\n    const g = document.getElementById(\'s1WheelGroup\');\n    const readout = document.getElementById(\'s1TurnReadout\');\n    if (g) g.setAttribute(\'transform\', `rotate(${s1Angle})`);\n    if (readout) readout.textContent = `${s1Angle}° (${Math.round((s1Angle/360)*100)/100} Turn)`;\n}\nfunction s1Reset() {\n    s1SetTurn(0, \'0 Turns\');\n}\n\n// Sim 2: Turn Types\nfunction s2SetTurn(deg, label) {\n    const pointer = document.getElementById(\'s2PointerGroup\');\n    const wedge = document.getElementById(\'s2WedgeArc\');\n    const readout = document.getElementById(\'s2FractionReadout\');\n    if (pointer) pointer.setAttribute(\'transform\', `rotate(${deg})`);\n    if (readout) readout.textContent = label;\n\n    if (wedge) {\n        if (deg === 0) {\n            wedge.setAttribute(\'d\', \'\');\n        } else if (deg === 360) {\n            wedge.setAttribute(\'d\', \'M 0,0 L 0,-120 A 120,120 0 1,1 -0.01,-120 Z\');\n        } else {\n            const rad = (deg - 90) * Math.PI / 180;\n            const x = 120 * Math.cos(rad);\n            const y = 120 * Math.sin(rad);\n            const largeArc = deg > 180 ? 1 : 0;\n            wedge.setAttribute(\'d\', `M 0,0 L 0,-120 A 120,120 0 ${largeArc},1 ${x},${y} Z`);\n        }\n    }\n    playSound(\'click\');\n}\n\n// Sim 3: What Is Angle\nlet s3Length = 160;\nlet s3Angle = 45;\nfunction s3UpdateAngle(deg) {\n    s3Angle = parseInt(deg, 10);\n    const rad = -s3Angle * Math.PI / 180;\n    const x = s3Length * Math.cos(rad);\n    const y = s3Length * Math.sin(rad);\n\n    const arm2 = document.getElementById(\'s3Arm2\');\n    const arrow = document.getElementById(\'s3Arm2Arrow\');\n    const readout = document.getElementById(\'s3AngleReadout\');\n    const sliderVal = document.getElementById(\'s3SliderVal\');\n    const arc = document.getElementById(\'s3Arc\');\n    const arcText = document.getElementById(\'s3ArcText\');\n\n    if (arm2) {\n        arm2.setAttribute(\'x2\', x);\n        arm2.setAttribute(\'y2\', y);\n    }\n    if (arrow) {\n        const ax = (s3Length + 6) * Math.cos(rad);\n        const ay = (s3Length + 6) * Math.sin(rad);\n        arrow.setAttribute(\'points\', `${ax},${ay} ${x-5},${y-5} ${x-5},${y+5}`);\n    }\n    if (readout) readout.textContent = `Angle: ${s3Angle}°`;\n    if (sliderVal) sliderVal.textContent = `${s3Angle}°`;\n\n    // Dynamic Arc\n    if (arc) {\n        if (s3Angle > 0) {\n            const arcR = 50;\n            const ax = arcR * Math.cos(rad);\n            const ay = arcR * Math.sin(rad);\n            const largeArc = s3Angle > 180 ? 1 : 0;\n            arc.setAttribute(\'d\', `M ${arcR},0 A ${arcR},${arcR} 0 ${largeArc},0 ${ax},${ay}`);\n        } else {\n            arc.setAttribute(\'d\', \'\');\n        }\n    }\n    if (arcText) {\n        const midRad = (-s3Angle / 2) * Math.PI / 180;\n        arcText.setAttribute(\'x\', 65 * Math.cos(midRad));\n        arcText.setAttribute(\'y\', 65 * Math.sin(midRad));\n        arcText.textContent = `${s3Angle}°`;\n    }\n}\nfunction s3UpdateLength(len) {\n    s3Length = parseInt(len, 10);\n    const arm1 = document.getElementById(\'s3Arm1\');\n    const arm1Arrow = document.getElementById(\'s3Arm1Arrow\');\n    if (arm1) arm1.setAttribute(\'x2\', s3Length);\n    if (arm1Arrow) arm1Arrow.setAttribute(\'points\', `${s3Length+6},0 ${s3Length-6},-5 ${s3Length-6},5`);\n    s3UpdateAngle(s3Angle);\n}\n\n// Sim 4: Right Angle\nfunction s4SetPreset(deg, name) {\n    const readout = document.getElementById(\'s4StatusReadout\');\n    if (readout) readout.textContent = `${name}: 90° Right Angle`;\n    playSound(\'correct\');\n}\n\n// Sim 5: Acute Angle\nfunction s5Update(deg) {\n    const angle = parseInt(deg, 10);\n    const rad = -angle * Math.PI / 180;\n    const x = 160 * Math.cos(rad);\n    const y = 160 * Math.sin(rad);\n\n    const blade2 = document.querySelector(\'#s5Blade2Group line\');\n    const bladeCircle = document.querySelector(\'#s5Blade2Group circle\');\n    const arc = document.getElementById(\'s5Arc\');\n    const label = document.getElementById(\'s5ArcLabel\');\n    const readout = document.getElementById(\'s5Readout\');\n    const valText = document.getElementById(\'s5Val\');\n\n    if (blade2) {\n        blade2.setAttribute(\'x2\', x);\n        blade2.setAttribute(\'y2\', y);\n    }\n    if (bladeCircle) {\n        bladeCircle.setAttribute(\'cx\', x);\n        bladeCircle.setAttribute(\'cy\', y);\n    }\n    if (arc) {\n        const r = 55;\n        const ax = r * Math.cos(rad);\n        const ay = r * Math.sin(rad);\n        arc.setAttribute(\'d\', `M 0,0 L ${r},0 A ${r},${r} 0 0,0 ${ax},${ay} Z`);\n    }\n    if (label) {\n        const midRad = (-angle / 2) * Math.PI / 180;\n        label.setAttribute(\'x\', 70 * Math.cos(midRad));\n        label.setAttribute(\'y\', 70 * Math.sin(midRad));\n        label.textContent = `${angle}°`;\n    }\n    if (readout) readout.textContent = `Acute Angle: ${angle}° (< 90°)`;\n    if (valText) valText.textContent = `${angle}°`;\n}\n\n// Sim 6: Obtuse Angle\nfunction s6Update(deg) {\n    const angle = parseInt(deg, 10);\n    const rad = (180 - angle) * Math.PI / 180;\n    const x = -130 * Math.cos(rad);\n    const y = -130 * Math.sin(rad);\n\n    const arm = document.querySelector(\'#s6ArmGroup line\');\n    const armCircle = document.querySelector(\'#s6ArmGroup circle\');\n    const arc = document.getElementById(\'s6Arc\');\n    const label = document.getElementById(\'s6ArcLabel\');\n    const readout = document.getElementById(\'s6Readout\');\n    const valText = document.getElementById(\'s6Val\');\n\n    if (arm) {\n        arm.setAttribute(\'x2\', x);\n        arm.setAttribute(\'y2\', y);\n    }\n    if (armCircle) {\n        armCircle.setAttribute(\'cx\', x);\n        armCircle.setAttribute(\'cy\', y);\n    }\n    if (arc) {\n        const r = 50;\n        const ax = -r * Math.cos(rad);\n        const ay = -r * Math.sin(rad);\n        arc.setAttribute(\'d\', `M 0,0 L 50,0 A 50,50 0 0,0 ${ax},${ay} Z`);\n    }\n    if (label) {\n        label.textContent = `${angle}°`;\n    }\n    if (readout) readout.textContent = `Obtuse Angle: ${angle}° (> 90°, < 180°)`;\n    if (valText) valText.textContent = `${angle}°`;\n}\n\n// Sim 7: Straight Angle\nfunction s7Step(deg) {\n    const readout = document.getElementById(\'s7Readout\');\n    const leftArm = document.getElementById(\'s7ArmLeftGroup\');\n    if (deg === 0) {\n        if (leftArm) leftArm.setAttribute(\'transform\', \'rotate(0)\');\n        if (readout) readout.textContent = \'Reset: Base 0°\';\n    } else if (deg === 90) {\n        if (leftArm) leftArm.setAttribute(\'transform\', \'rotate(90)\');\n        if (readout) readout.textContent = \'1st 1/4 Turn = 90° Right Angle\';\n        playSound(\'click\');\n    } else if (deg === 180) {\n        if (leftArm) leftArm.setAttribute(\'transform\', \'rotate(180)\');\n        if (readout) readout.textContent = \'Two 1/4 Turns = 180° Straight Angle\';\n        playSound(\'correct\');\n    }\n}\n\n// Sim 8: Accordion Fan\nfunction s8SetAngle(deg) {\n    const angle = parseInt(deg, 10);\n    const bladesGroup = document.getElementById(\'s8FanBlades\');\n    const readout = document.getElementById(\'s8FanReadout\');\n    const sliderVal = document.getElementById(\'s8SliderVal\');\n    const slider = document.getElementById(\'s8Slider\');\n\n    if (slider) slider.value = angle;\n    if (sliderVal) sliderVal.textContent = `${angle}°`;\n\n    let typeStr = \'Acute Angle\';\n    if (angle === 90) typeStr = \'Right Angle (1/4 Turn)\';\n    else if (angle < 90) typeStr = \'Acute Angle (< 90°)\';\n    else if (angle < 180) typeStr = \'Obtuse Angle (> 90°)\';\n    else typeStr = \'Straight Angle (180°)\';\n\n    if (readout) readout.textContent = `Fan Spread: ${angle}° (${typeStr})`;\n\n    if (bladesGroup) {\n        bladesGroup.innerHTML = \'\';\n        const numPleats = 10;\n        const step = angle / numPleats;\n        const startRad = (-angle / 2 - 90) * Math.PI / 180;\n\n        for (let i = 0; i <= numPleats; i++) {\n            const curRad = startRad + (i * step * Math.PI / 180);\n            const x = 110 * Math.cos(curRad);\n            const y = 110 * Math.sin(curRad);\n            const line = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');\n            line.setAttribute(\'x1\', \'0\');\n            line.setAttribute(\'y1\', \'10\');\n            line.setAttribute(\'x2\', x);\n            line.setAttribute(\'y2\', y + 10);\n            line.setAttribute(\'stroke\', i % 2 === 0 ? \'#f59e0b\' : \'#fbbf24\');\n            line.setAttribute(\'stroke-width\', \'3\');\n            bladesGroup.appendChild(line);\n\n            if (i > 0) {\n                const prevRad = startRad + ((i - 1) * step * Math.PI / 180);\n                const px = 110 * Math.cos(prevRad);\n                const py = 110 * Math.sin(prevRad);\n                const poly = document.createElementNS(\'http://www.w3.org/2000/svg\', \'polygon\');\n                poly.setAttribute(\'points\', `0,10 ${px},${py+10} ${x},${y+10}`);\n                poly.setAttribute(\'fill\', i % 2 === 0 ? \'#d97706\' : \'#b45309\');\n                poly.setAttribute(\'fill-opacity\', \'0.45\');\n                bladesGroup.insertBefore(poly, line);\n            }\n        }\n    }\n}\n\n// Sim 9: Angles Around\nlet s9CurrentObj = \'door\';\nlet s9Angle = 50;\nfunction s9SelectObject(obj) {\n    s9CurrentObj = obj;\n    [\'door\', \'roof\', \'laptop\', \'split\'].forEach(t => {\n        const btn = document.getElementById(`s9Tab${t.charAt(0).toUpperCase() + t.slice(1)}`);\n        if (btn) {\n            if (t === obj) {\n                btn.className = \'px-2 py-1 bg-teal-500/30 text-teal-200 border border-teal-500/40 rounded text-xs font-bold transition\';\n            } else {\n                btn.className = \'px-2 py-1 bg-slate-800 text-slate-300 border border-slate-700 rounded text-xs font-bold transition\';\n            }\n        }\n    });\n    s9UpdateAngle(s9Angle);\n}\n\nfunction s9UpdateAngle(deg) {\n    s9Angle = parseInt(deg, 10);\n    const art = document.getElementById(\'s9ObjectArt\');\n    const arc = document.getElementById(\'s9AngleArc\');\n    const text = document.getElementById(\'s9AngleText\');\n    const badge = document.getElementById(\'s9CategoryBadge\');\n    const valText = document.getElementById(\'s9Val\');\n\n    if (valText) valText.textContent = `${s9Angle}°`;\n\n    let cat = \'Acute Angle\';\n    if (s9Angle === 90) cat = \'Right Angle (90°)\';\n    else if (s9Angle < 90) cat = \'Acute Angle (< 90°)\';\n    else if (s9Angle < 180) cat = \'Obtuse Angle (> 90°)\';\n    else cat = \'Straight Angle (180°)\';\n\n    if (badge) badge.textContent = `${cat}: ${s9Angle}°`;\n\n    const rad = -s9Angle * Math.PI / 180;\n    const x = 100 * Math.cos(rad);\n    const y = 100 * Math.sin(rad);\n\n    if (art) {\n        art.innerHTML = \'\';\n        if (s9CurrentObj === \'door\') {\n            art.innerHTML = `\n                <line x1="0" y1="0" x2="100" y2="0" stroke="#64748b" stroke-width="6" stroke-linecap="round"/>\n                <line x1="0" y1="0" x2="${x}" y2="${y}" stroke="#14b8a6" stroke-width="6" stroke-linecap="round"/>\n                <circle cx="0" cy="0" r="7" fill="#0d9488"/>\n                <text x="50" y="20" font-size="10" fill="#94a3b8">Wall Frame</text>\n                <text x="${x/2 - 10}" y="${y/2 - 10}" font-size="10" fill="#2dd4bf">Open Door</text>\n            `;\n        } else if (s9CurrentObj === \'roof\') {\n            art.innerHTML = `\n                <line x1="0" y1="-80" x2="-80" y2="20" stroke="#f59e0b" stroke-width="5"/>\n                <line x1="0" y1="-80" x2="${Math.abs(x)}" y2="20" stroke="#f59e0b" stroke-width="5"/>\n                <circle cx="0" cy="-80" r="6" fill="#b45309"/>\n                <text x="0" y="-95" text-anchor="middle" font-size="10" fill="#fcd34d">Tent Peak Angle</text>\n            `;\n        } else if (s9CurrentObj === \'laptop\') {\n            art.innerHTML = `\n                <line x1="0" y1="0" x2="90" y2="0" stroke="#94a3b8" stroke-width="5" stroke-linecap="round"/>\n                <line x1="0" y1="0" x2="${x}" y2="${y}" stroke="#38bdf8" stroke-width="5" stroke-linecap="round"/>\n                <circle cx="0" cy="0" r="5" fill="#0284c7"/>\n                <text x="45" y="16" font-size="10" fill="#94a3b8">Keyboard Base</text>\n                <text x="${x/2}" y="${y/2 - 12}" font-size="10" fill="#38bdf8">Screen</text>\n            `;\n        } else {\n            art.innerHTML = `\n                <line x1="0" y1="0" x2="80" y2="0" stroke="#f43f5e" stroke-width="5" stroke-linecap="round"/>\n                <line x1="0" y1="0" x2="${x}" y2="${y}" stroke="#f43f5e" stroke-width="5" stroke-linecap="round"/>\n                <circle cx="0" cy="0" r="6" fill="#be123c"/>\n                <circle cx="0" cy="-25" r="10" fill="#fda4af"/>\n                <text x="0" y="-40" text-anchor="middle" font-size="10" fill="#fda4af">Gymnast Splits</text>\n            `;\n        }\n    }\n\n    if (arc) {\n        const ar = 40;\n        const ax = ar * Math.cos(rad);\n        const ay = ar * Math.sin(rad);\n        arc.setAttribute(\'d\', `M ${ar},0 A ${ar},${ar} 0 0,0 ${ax},${ay}`);\n    }\n    if (text) {\n        text.textContent = `${s9Angle}°`;\n    }\n}\n\n// Sim 10: Folded Tester\nfunction s10ShowStep(step) {\n    const fullDisc = document.getElementById(\'s10FullDisc\');\n    const readout = document.getElementById(\'s10WedgesReadout\');\n    if (step === 1) {\n        if (fullDisc) fullDisc.innerHTML = `\n            <path d="M 0,0 L -100,0 A 100,100 0 0,1 100,0 Z" fill="#1e293b" stroke="#3b82f6" stroke-width="3"/>\n            <line x1="-100" y1="0" x2="100" y2="0" stroke="#60a5fa" stroke-width="2.5"/>\n            <text x="0" y="-35" text-anchor="middle" font-size="12" font-weight="bold" fill="#93c5fd">Fold 1: 1/2 Turn (180°)</text>\n        `;\n        if (readout) readout.textContent = \'Fold 1: Circle in Half = 1/2 Turn\';\n    } else if (step === 2) {\n        if (fullDisc) fullDisc.innerHTML = `\n            <path d="M 0,0 L 0,-100 A 100,100 0 0,1 100,0 Z" fill="#1e293b" stroke="#3b82f6" stroke-width="3"/>\n            <rect x="0" y="-20" width="20" height="20" fill="#3b82f6" fill-opacity="0.3" stroke="#60a5fa"/>\n            <text x="45" y="-45" text-anchor="middle" font-size="12" font-weight="bold" fill="#93c5fd">Fold 2: 1/4 Turn (90°)</text>\n        `;\n        if (readout) readout.textContent = \'Fold 2: Semicircle in Half = 1/4 Turn\';\n    } else if (step === 3) {\n        if (fullDisc) fullDisc.innerHTML = `\n            <path d="M 0,0 L 0,-100 A 100,100 0 0,1 70.7,-70.7 Z" fill="#1e293b" stroke="#3b82f6" stroke-width="3"/>\n            <text x="35" y="-55" text-anchor="middle" font-size="11" font-weight="bold" fill="#93c5fd">Fold 3: 1/8 Turn (45°)</text>\n        `;\n        if (readout) readout.textContent = \'Fold 3: Quadrant in Half = 1/8 Turn (45°)\';\n    } else {\n        if (fullDisc) {\n            fullDisc.innerHTML = `\n                <circle cx="0" cy="0" r="100" fill="#1e293b" stroke="#3b82f6" stroke-width="3"/>\n                <line x1="0" y1="-100" x2="0" y2="100" stroke="#60a5fa" stroke-width="2" stroke-dasharray="3 3"/>\n                <line x1="-100" y1="0" x2="100" y2="0" stroke="#60a5fa" stroke-width="2" stroke-dasharray="3 3"/>\n                <line x1="-70.7" y1="-70.7" x2="70.7" y2="70.7" stroke="#60a5fa" stroke-width="2" stroke-dasharray="3 3"/>\n                <line x1="-70.7" y1="70.7" x2="70.7" y2="-70.7" stroke="#60a5fa" stroke-width="2" stroke-dasharray="3 3"/>\n                <text x="25" y="-60" font-size="11" font-weight="bold" fill="#93c5fd">1 (45°)</text>\n                <text x="60" y="-25" font-size="11" font-weight="bold" fill="#93c5fd">2</text>\n                <text x="60" y="35" font-size="11" font-weight="bold" fill="#93c5fd">3</text>\n                <text x="25" y="70" font-size="11" font-weight="bold" fill="#93c5fd">4</text>\n                <text x="-35" y="70" font-size="11" font-weight="bold" fill="#93c5fd">5</text>\n                <text x="-70" y="35" font-size="11" font-weight="bold" fill="#93c5fd">6</text>\n                <text x="-70" y="-25" font-size="11" font-weight="bold" fill="#93c5fd">7</text>\n                <text x="-35" y="-60" font-size="11" font-weight="bold" fill="#93c5fd">8</text>\n            `;\n        }\n        if (readout) readout.textContent = \'Unfolded: 8 Wedges (45° Each)\';\n        s10SetWedges(2);\n    }\n    playSound(\'click\');\n}\n\nfunction s10SetWedges(count) {\n    const c = parseInt(count, 10);\n    const wedgeHighlight = document.getElementById(\'s10WedgeHighlight\');\n    const wedgeCountText = document.getElementById(\'s10WedgeCount\');\n    const deg = c * 45;\n    if (wedgeCountText) wedgeCountText.textContent = `${c} (${deg}°)`;\n\n    if (wedgeHighlight) {\n        if (c === 8) {\n            wedgeHighlight.setAttribute(\'d\', \'M 0,0 L 0,-100 A 100,100 0 1,1 -0.01,-100 Z\');\n        } else {\n            const rad = (deg - 90) * Math.PI / 180;\n            const x = 100 * Math.cos(rad);\n            const y = 100 * Math.sin(rad);\n            const largeArc = deg > 180 ? 1 : 0;\n            wedgeHighlight.setAttribute(\'d\', `M 0,0 L 0,-100 A 100,100 0 ${largeArc},1 ${x},${y} Z`);\n        }\n    }\n}\n\n// Sim 11: Six-Part Tester\nfunction s11SetSector(count) {\n    const c = parseInt(count, 10);\n    const deg = c * 60;\n    const pointer = document.getElementById(\'s11StrawPointer\');\n    const readout = document.getElementById(\'s11SectorReadout\');\n    if (pointer) pointer.setAttribute(\'transform\', `rotate(${deg})`);\n    if (readout) readout.textContent = `${c}/6 Turn (${deg}°)`;\n    playSound(\'click\');\n}\n\n// Sim 12: Combining Turns\nfunction s12SetFormula(formula, deg) {\n    const wedge = document.getElementById(\'s12CombinedWedge\');\n    const pointer = document.getElementById(\'s12PointerGroup\');\n    const readout = document.getElementById(\'s12TotalReadout\');\n    const eq = document.getElementById(\'s12Equation\');\n\n    if (pointer) pointer.setAttribute(\'transform\', `rotate(${deg})`);\n    if (wedge) {\n        const rad = (deg - 90) * Math.PI / 180;\n        const x = 100 * Math.cos(rad);\n        const y = 100 * Math.sin(rad);\n        const largeArc = deg > 180 ? 1 : 0;\n        wedge.setAttribute(\'d\', `M 0,0 L 0,-100 A 100,100 0 ${largeArc},1 ${x},${y} Z`);\n    }\n\n    if (formula === \'1/4 + 1/8\') {\n        if (readout) readout.textContent = \'Total Turn: 3/8 (135°)\';\n        if (eq) eq.textContent = \'1/4 Turn + 1/8 Turn = 2/8 + 1/8 = 3/8 Turn (135° Obtuse Angle)\';\n    } else if (formula === \'1/2 - 1/8\') {\n        if (readout) readout.textContent = \'Remaining Turn: 3/8 (135°)\';\n        if (eq) eq.textContent = \'1/2 Turn - 1/8 Turn = 4/8 - 1/8 = 3/8 Turn (135° Obtuse Angle)\';\n    } else if (formula === \'1/4 + 1/4\') {\n        if (readout) readout.textContent = \'Total Turn: 1/2 (180°)\';\n        if (eq) eq.textContent = \'1/4 Turn + 1/4 Turn = 2/4 = 1/2 Turn (180° Straight Angle)\';\n    } else if (formula === \'1/8 + 1/8\') {\n        if (readout) readout.textContent = \'Total Turn: 1/4 (90°)\';\n        if (eq) eq.textContent = \'1/8 Turn + 1/8 Turn = 2/8 = 1/4 Turn (90° Right Angle)\';\n    }\n    playSound(\'click\');\n}\n\n// Sim 13: Clock Turns\nfunction s13InitClock() {\n    const marksGroup = document.getElementById(\'s13HourMarks\');\n    if (!marksGroup || marksGroup.children.length > 0) return;\n\n    for (let h = 1; h <= 12; h++) {\n        const rad = (h * 30 - 90) * Math.PI / 180;\n        const tx = 88 * Math.cos(rad);\n        const ty = 88 * Math.sin(rad);\n        const text = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');\n        text.setAttribute(\'x\', tx);\n        text.setAttribute(\'y\', ty + 4);\n        text.setAttribute(\'text-anchor\', \'middle\');\n        text.setAttribute(\'font-size\', \'11\');\n        text.setAttribute(\'font-weight\', \'bold\');\n        text.setAttribute(\'fill\', \'#fde047\');\n        text.textContent = h;\n        marksGroup.appendChild(text);\n    }\n}\n\nfunction s13SetMinutes(min) {\n    const deg = (min / 60) * 360;\n    const hand = document.getElementById(\'s13MinuteHand\');\n    const wedge = document.getElementById(\'s13SweptWedge\');\n    const readout = document.getElementById(\'s13ClockReadout\');\n\n    if (hand) hand.setAttribute(\'transform\', `rotate(${deg})`);\n\n    let turnFraction = \'1/4 Turn\';\n    if (min === 15) turnFraction = \'1/4 Turn (90° Right Angle)\';\n    else if (min === 30) turnFraction = \'1/2 Turn (180° Straight Angle)\';\n    else if (min === 45) turnFraction = \'3/4 Turn (270°)\';\n    else if (min === 60) turnFraction = \'1 Full Turn (360°)\';\n\n    if (readout) readout.textContent = `${min} Min = ${turnFraction}`;\n\n    if (wedge) {\n        if (deg === 360) {\n            wedge.setAttribute(\'d\', \'M 0,0 L 0,-90 A 90,90 0 1,1 -0.01,-90 Z\');\n        } else {\n            const rad = (deg - 90) * Math.PI / 180;\n            const x = 90 * Math.cos(rad);\n            const y = 90 * Math.sin(rad);\n            const largeArc = deg > 180 ? 1 : 0;\n            wedge.setAttribute(\'d\', `M 0,0 L 0,-90 A 90,90 0 ${largeArc},1 ${x},${y} Z`);\n        }\n    }\n    playSound(\'click\');\n}\n\n// Sim 14: Clockwise Motion (Righty-Tighty)\nlet s14Angle = 0;\nfunction s14Rotate(deg) {\n    s14Angle += deg;\n    const handle = document.getElementById(\'s14HandleGroup\');\n    const status = document.getElementById(\'s14TapStatus\');\n    const drips = document.getElementById(\'s14WaterDrips\');\n\n    if (handle) handle.setAttribute(\'transform\', `rotate(${s14Angle})`);\n    if (status) status.textContent = `Tightened Clockwise: ${s14Angle}° (Sealed Tight)`;\n    if (drips) drips.setAttribute(\'opacity\', \'0\');\n    playSound(\'click\');\n}\nfunction s14Reset() {\n    s14Angle = 0;\n    const handle = document.getElementById(\'s14HandleGroup\');\n    const status = document.getElementById(\'s14TapStatus\');\n    const drips = document.getElementById(\'s14WaterDrips\');\n    if (handle) handle.setAttribute(\'transform\', \'rotate(0)\');\n    if (status) status.textContent = \'Valve Normal: Clockwise Tightens Tap\';\n    if (drips) drips.setAttribute(\'opacity\', \'0\');\n}\n\n// Sim 15: Anti-Clockwise Motion (Lefty-Loosey)\nlet s15Angle = 0;\nfunction s15Rotate(deg) {\n    s15Angle += deg;\n    const cap = document.getElementById(\'s15CapGroup\');\n    const status = document.getElementById(\'s15Status\');\n    const splash = document.getElementById(\'s15Splash\');\n\n    const lift = Math.min(Math.abs(s15Angle) / 5, 25);\n    if (cap) cap.setAttribute(\'transform\', `translate(0, ${-lift})`);\n    if (status) status.textContent = `Loosened Anti-Clockwise: ${Math.abs(s15Angle)}° (Open!)`;\n    if (splash) splash.setAttribute(\'opacity\', \'1\');\n    playSound(\'click\');\n}\nfunction s15Reset() {\n    s15Angle = 0;\n    const cap = document.getElementById(\'s15CapGroup\');\n    const status = document.getElementById(\'s15Status\');\n    const splash = document.getElementById(\'s15Splash\');\n    if (cap) cap.setAttribute(\'transform\', \'translate(0, 0)\');\n    if (status) status.textContent = \'Cap Screwed On Tight: Turn Anti-Clockwise to Loosen\';\n    if (splash) splash.setAttribute(\'opacity\', \'0\');\n}\n\n// Sim 16: Compass Turns\nlet s16Angle = 0;\nconst cardinalNames = {\n    0: \'North (0°)\',\n    45: \'North-East (45°)\',\n    90: \'East (90°)\',\n    135: \'South-East (135°)\',\n    180: \'South (180°)\',\n    225: \'South-West (225°)\',\n    270: \'West (270°)\',\n    315: \'North-West (315°)\'\n};\n\nfunction s16Turn(deg, type) {\n    s16Angle = (s16Angle + deg) % 360;\n    if (s16Angle < 0) s16Angle += 360;\n\n    const needle = document.getElementById(\'s16Needle\');\n    const readout = document.getElementById(\'s16HeadingReadout\');\n    if (needle) needle.setAttribute(\'transform\', `rotate(${s16Angle})`);\n\n    const headingName = cardinalNames[s16Angle] || `${s16Angle}°`;\n    if (readout) readout.textContent = `Facing: ${headingName}`;\n    playSound(\'click\');\n}\nfunction s16Reset() {\n    s16Angle = 0;\n    const needle = document.getElementById(\'s16Needle\');\n    const readout = document.getElementById(\'s16HeadingReadout\');\n    if (needle) needle.setAttribute(\'transform\', \'rotate(0)\');\n    if (readout) readout.textContent = \'Facing: North (0°)\';\n}\n\n// Global initialization\nwindow.addEventListener(\'DOMContentLoaded\', () => {\n    initVoices();\n    if (\'speechSynthesis\' in window) {\n        window.speechSynthesis.onvoiceschanged = initVoices;\n    }\n    goToSlide(1);\n\n    // Keyboard navigation\n    window.addEventListener(\'keydown\', (e) => {\n        if (e.key === \'ArrowRight\') nextSlide();\n        else if (e.key === \'ArrowLeft\') prevSlide();\n        else if (e.key === \'Escape\') closeSolutionModal();\n    });\n});\n'
